$fpl$::jsonb) AS x(code text,playlist_id text,ord integer,confidence text,level text,match text);

DO $pre$ BEGIN
 IF (SELECT count(*) FROM _u)<>32 OR (SELECT count(DISTINCT code) FROM _u)<>32
 OR (SELECT sum(jsonb_array_length(placements)) FROM _u)<>32 OR (SELECT count(*) FROM _p)<>30 OR (SELECT count(*) FROM _pl)<>31
 OR (SELECT sum(u.ects) FROM _u u WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(u.placements) e WHERE e->>'role'='mandatory'))<>156
 OR (SELECT count(*) FROM _u u WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(u.placements) e WHERE e->>'group'='Opção I - Metodologia dos Desportos Náuticos' AND u.ects=7))<>2
 OR (SELECT count(*) FROM _u u WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(u.placements) e WHERE e->>'group'='Opção II - Metodologia das Atividades Desportivas' AND u.ects=7))<>2
 OR (SELECT count(*) FROM _u u WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(u.placements) e WHERE e->>'group'='Opção III' AND u.ects=5))<>2
 OR (SELECT count(*) FROM _u u WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(u.placements) e WHERE e->>'group'='Opção IV' AND u.ects=5))<>2
 OR EXISTS(SELECT 1 FROM _pl WHERE confidence NOT IN ('alta','média'))
 THEN RAISE EXCEPTION 'Unexpected Desporto manifest counts or ECTS (expected 156 mandatory + 7 + 7 + 5 + 5 = 180)'; END IF;
 IF EXISTS(SELECT 1 FROM _p WHERE id !~ '^PL[A-Za-z0-9_-]{10,60}$' OR url<>'https://www.youtube.com/playlist?list='||id
 OR length(trim(title))<3 OR videos<4 OR language NOT IN('pt-PT','pt-BR','en'))
 OR EXISTS(SELECT 1 FROM _pl t LEFT JOIN _p p ON p.id=t.playlist_id LEFT JOIN _u u ON u.code=t.code WHERE p.id IS NULL OR u.code IS NULL)
 THEN RAISE EXCEPTION 'Invalid playlist metadata or link'; END IF;
 IF EXISTS(SELECT 1 FROM facodi.courses WHERE (code='LDESP' OR slug='desporto'
 OR (external_source='ualg_official' AND external_id='1538')) AND id<>md5('facodi:ualg:1538:course:record')::uuid)
 THEN RAISE EXCEPTION 'Another course already uses LDESP, the slug desporto or UAlg 1538; reconcile manually'; END IF;
END $pre$;

INSERT INTO facodi.learning_objects(id,object_type,title,slug,description,objectives,keywords,tags,language,status,published,source_type,source_url,source_id,metadata)
VALUES(md5('facodi:ualg:1538:course')::uuid,'course','Licenciatura em Desporto','facodi-course-desporto',
 'Licenciatura da Escola Superior de Educação e Comunicação da Universidade do Algarve, com 180 ECTS em três anos. Treino desportivo, exercício e saúde, pedagogia e gestão do desporto, com natação, ténis, futebol e desportos náuticos, e um estágio de 30 ECTS no último semestre.','[]'::jsonb,ARRAY['Desporto','Treino desportivo','Exercício e saúde','Desportos náuticos','Pedagogia do desporto'],ARRAY['Desporto'],
 'pt','active',true,'import','https://www.ualg.pt/curso/1538','ualg:licenciatura:1538:course',
 jsonb_build_object('university_course_code','1538','official_academic_year','2026/27','official_plan_url','https://www.ualg.pt/curso/1538/plano',
 'source_quality','ualg_official_programme','curation_batch','facodi_ualg_1538_desporto_20261118'))
ON CONFLICT DO NOTHING;

INSERT INTO facodi.courses(id,learning_object_id,code,external_source,external_id,slug,title,normalized_title,summary,description_html,
 degree_type,language,school,source_url,plan_url,status,published,metadata,institution,ects_total,duration_semesters)
VALUES(md5('facodi:ualg:1538:course:record')::uuid,md5('facodi:ualg:1538:course')::uuid,'LDESP','ualg_official','1538','desporto',
 'Licenciatura em Desporto','Desporto','Licenciatura da Escola Superior de Educação e Comunicação da Universidade do Algarve, com 180 ECTS em três anos. Treino desportivo, exercício e saúde, pedagogia e gestão do desporto, com natação, ténis, futebol e desportos náuticos, e um estágio de 30 ECTS no último semestre.','<h2>Apresentação</h2><p>A licenciatura forma técnicos superiores de desporto para intervir no treino desportivo, no exercício e saúde e na recreação, nomeadamente nos desportos náuticos, em clubes, autarquias, organizações turísticas, health clubs e empresas. Dá também reconhecimento de componentes dos cursos de treinadores do IPDJ em ténis, natação, canoagem e vela.</p><h2>Plano de estudos</h2><p>24 unidades curriculares obrigatórias e quatro grupos de opção: Metodologia dos Desportos Náuticos (canoagem ou vela), Metodologia das Atividades Desportivas (futebol ou ténis), Opção III e Opção IV. O 1.º ano trata as bases biológicas, motoras e de investigação; o 2.º, o treino, a biomecânica, a condição física e a gestão; o 3.º, a psicologia, a sociologia e a segurança no desporto, e termina com um estágio de 30 ECTS.</p><h2>Na FACODI</h2><p>As unidades curriculares ligam a playlists abertas do YouTube, escolhidas a partir do programa da ficha oficial de cada UC.</p>',
 'Licenciatura','pt','Escola Superior de Educação e Comunicação','https://www.ualg.pt/curso/1538','https://www.ualg.pt/curso/1538/plano','active',true,
 jsonb_build_object('official_course_id','1538','official_academic_year','2026/27','official_plan_url','https://www.ualg.pt/curso/1538/plano',
 'official_program_verified',true,'official_ects_total',180,'official_unit_count',32,'mandatory_unit_count',24,
 'curriculum_contains_elective_alternatives',true,'alternative_pathways_not_additive',true,
 'education_subsystem','Ensino Politécnico','thematic_area','Ciências Sociais e da Educação','teaching_language','Português',
 'source_quality','ualg_official_programme','curriculum_review_status','approved_official_plan','curation_batch','facodi_ualg_1538_desporto_20261118'),
 'Universidade do Algarve',180,6)
ON CONFLICT DO NOTHING;

